{
  "html": "<header class="e1-header" data-ui-unit="E1">
  <h2 class="e1-title">멘토 찾기</h2>
  <div class="e1-tools">
    <img src="assets/reference/bell.svg" alt="알림" class="e1-icon">
    <img src="assets/reference/heart.svg" alt="찜" class="e1-icon">
    <img src="assets/reference/user-round.svg" alt="프로필" class="e1-icon">
  </div>
</header>",
  "css": ".e1-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 54px;
  min-width: 0;
}

.e1-title {
  font-size: 18px;
  font-weight: 700;
  color: #283548;
  margin: 0;
  white-space: nowrap;
}

.e1-tools {
  display: flex;
  align-items: center;
  gap: 20px;
  flex-shrink: 0;
}

.e1-icon {
  width: 24px;
  height: 24px;
  color: #566273;
}"
}
